const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  if (payload.role && payload.role !== 'architect' && payload.role !== 'super_admin' && payload.role !== 'owner') {
    return [{ json: { _error: 'FORBIDDEN_ROLE', _status: 403, _details: 'Solo architect/owner pueden gestionar billing' } }];
  }
  const body = $input.first().json.body || {};
  const validTiers = ['starter','pro','equipo'];
  const tier = (body.tier || '').trim();
  if (!validTiers.includes(tier)) {
    return [{ json: { _error: 'INVALID_TIER', _status: 400, _details: 'tier debe ser starter|pro|equipo' } }];
  }
  return [{ json: { user_id: payload.sub, tenant_id: payload.tenant_id, role: payload.role || 'architect', email: payload.email || null, tier, request_id: 'req_' + Math.random().toString(36).slice(2, 10) }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode + Validate').first().json;
const planRows = $('Load Plan + Tenant').all().map(i => i.json).filter(r => r && r.tier_slug);
if (planRows.length === 0) return [{ json: { _error: 'PLAN_OR_TENANT_NOT_FOUND', _status: 404, _details: 'Plan ' + sess.tier + ' o tenant inexistente', request_id: sess.request_id }}];
const plan = planRows[0];
const configRows = $input.all().map(i => i.json).filter(c => c && c.key);
const cfg = Object.fromEntries(configRows.map(r => [r.key, r.value]));
if (!cfg.stripe_secret_key || cfg.stripe_secret_key.startsWith('sk_test_REPLACE') || cfg.stripe_secret_key.startsWith('sk_live_REPLACE')) {
  return [{ json: { _error: 'STRIPE_NOT_CONFIGURED', _status: 503, _details: 'system_config.stripe_secret_key sin configurar', request_id: sess.request_id }}];
}
if (!plan.stripe_price_id || plan.stripe_price_id.startsWith('price_REPLACE')) {
  return [{ json: { _error: 'STRIPE_PRICE_ID_MISSING', _status: 503, _details: 'subscription_plans.stripe_price_id para tier ' + plan.tier_slug + ' sin configurar', request_id: sess.request_id }}];
}
// billing_success_url debe contener literalmente {CHECKOUT_SESSION_ID} - Stripe lo sustituye al redirigir.
const successUrl = cfg.billing_success_url || 'http://localhost:5173/?session_id={CHECKOUT_SESSION_ID}#billing';
const cancelUrl = cfg.billing_cancel_url || 'http://localhost:5173/?canceled=true#billing';

// Stripe Checkout Session body (URL-encoded form)
const form = {
  'mode': 'subscription',
  'line_items[0][price]': plan.stripe_price_id,
  'line_items[0][quantity]': '1',
  'success_url': successUrl,
  'cancel_url': cancelUrl,
  'client_reference_id': sess.tenant_id,
  'subscription_data[trial_period_days]': String(plan.trial_days || 14),
  'subscription_data[metadata][tenant_id]': sess.tenant_id,
  'subscription_data[metadata][tier_slug]': plan.tier_slug,
  'metadata[tenant_id]': sess.tenant_id,
  'metadata[tier_slug]': plan.tier_slug,
  'allow_promotion_codes': 'true',
  'billing_address_collection': 'auto',
  'locale': 'es'
};
// Reusar customer si ya existe
if (plan.existing_customer_id) {
  form['customer'] = plan.existing_customer_id;
} else {
  const email = sess.email || plan.tenant_email;
  if (email) form['customer_email'] = email;
}
const formStr = Object.entries(form).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
return [{ json: {
  tenant_id: sess.tenant_id,
  tier: plan.tier_slug,
  plan_name: plan.name,
  request_id: sess.request_id,
  stripe_secret_key: cfg.stripe_secret_key,
  form_string: formStr
}}];

const r = $input.first()?.json || {};
const prep = $('Prepare Checkout').first().json;
if (r.error) {
  return [{ json: { _error: 'STRIPE_ERROR', _status: 502, _details: r.error.message || JSON.stringify(r.error).slice(0, 400), _stripe_code: r.error.code, _stripe_type: r.error.type, request_id: prep.request_id }}];
}
if (!r.id || !r.url) {
  return [{ json: { _error: 'STRIPE_INVALID_RESPONSE', _status: 502, _details: 'Stripe no devolvio id/url: ' + JSON.stringify(r).slice(0, 400), request_id: prep.request_id }}];
}
return [{ json: { session_id: r.id, url: r.url, customer: r.customer, mode: r.mode, status: r.status, expires_at: r.expires_at, request_id: prep.request_id }}];
